CREATE FUNCTION public.save_driver_transactions(p jsonb) RETURNS uuid[] LANGUAGE plpgsql SET search_path=public AS $$ DECLARE r jsonb; ids uuid[]:='{}'; BEGIN IF jsonb_typeof(p)<>'array' THEN RAISE EXCEPTION 'Entry list required'; END IF; FOR r IN SELECT * FROM jsonb_array_elements(p) LOOP ids:=array_append(ids,public.save_driver_transaction(r)); END LOOP; RETURN ids; END $$;
REVOKE ALL ON FUNCTION public.save_driver_transactions(jsonb) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.save_driver_transactions(jsonb) TO authenticated,service_role;
DO $$ DECLARE d text; BEGIN d:=pg_get_functiondef('public.save_driver_transaction(jsonb)'::regprocedure); d:=replace(d,'IF FOUND AND(oldrow.business_id<>v_biz OR oldrow.is_cancelled) THEN RAISE EXCEPTION ''Entry unavailable or access denied''; END IF;','IF FOUND AND oldrow.business_id<>v_biz THEN RAISE EXCEPTION ''Entry unavailable or access denied''; END IF; IF oldrow.is_cancelled THEN IF coalesce((p->>''cancel'')::boolean,false) THEN RETURN v_id; END IF; RAISE EXCEPTION ''Cancelled entry cannot be edited''; END IF;'); EXECUTE d; END $$;